export type KitchenSinkBulkCompanyData = {
    body: {
        /**
         * Your Fiber API key
         */
        apiKey: string;
        companies: Array<{
            /**
             * A unique identifier for the company. Accepts one of: linkedinSlug, linkedinUrl, or linkedinOrgID. Providing this increases the accuracy and speed of the lookup. If this is provided, you do not need to supply companyName or companyDomain.
             */
            companyIdentifier?: {
                identifier: 'linkedinSlug';
                /**
                 * The linkedin slug of the company the person is currently working at
                 */
                value: string;
            } | {
                identifier: 'linkedinUrl';
                /**
                 * The linkedin URL of the company the person is currently working at
                 */
                value: string;
            } | {
                identifier: 'linkedinOrgID';
                /**
                 * The linkedin organization ID of the company the person currently working at
                 */
                value: string;
            } | null;
            companyName?: {
                /**
                 * The name of the company. We match a company only if all of the input words are matched.
                 */
                value?: string | null;
            } | null;
            companyDomain?: {
                /**
                 * The domain of the company. URL parts like https, www, etc. would automatically be removed. However, note that parts like subdomains and path parts are not removed. This is intentional so users could match with domains like `instagram.com/company` or `my_company.netlify.app`.
                 */
                value?: string | null;
            } | null;
            /**
             * The number of companies you want to fetch. Companies are sorted by best match first.
             */
            numCompanies?: number;
        }>;
    };
    path?: never;
    query?: never;
    url: '/v1/kitchen-sink/bulk/company';
};

